/// <summary>
/// PE Pricing POC Task 96965: Generate invoices for sales orders, validate account allocation.
/// Create discount claims in the std table and bypass the relation validation on discount id as this will come from PE
/// </summary>
[ExtensionOf(tableStr(GUPDiscountClaim))]
final class METGUPDiscountClaimTbl_Extension
{
}

Method.Source:
    /// <summary>
    /// Added as part of pricing POC to be able to enter a value in discount ID field from PE which does not exist as a discount in FO
    /// </summary>
    /// <param name = "p1">field id to validate</param>
    /// <returns>true if field validation successful; otherwise, false</returns>
    boolean validateField(FieldId p1)
    {
        boolean ret;

        ret = next validateField(p1);

        if (!ret && p1 == fieldNum(GUPDiscountClaim, DiscountId))
        {
            // bypass field validation with relation
            ret = true;
        }

        return ret;
    }

/// <summary>
/// CB790_DiscountClaim
/// similar to displayTotalClaimAmount(), display method to show the total GST amount for a discount claim
/// </summary>
/// <returns>Discount claim GST amount</returns>
display METGSTAmount METDisplayTotalGSTAmount()
{
    return this.METTotalGSTAmount();
}

/// <summary>
/// CB790_DiscountClaim
/// Method to calculate total GST amount from all discount claim transactions
/// </summary>
/// <returns>Discount claim GST amount</returns>
public METGSTAmount METTotalGSTAmount()
{
    GUPDiscountClaimTransaction discountClaimTransaction;
    select sum(METGSTAmount) from discountClaimTransaction
        where discountClaimTransaction.DiscountClaimId == this.DiscountClaimId;
    return discountClaimTransaction.METGSTAmount;
}

/// <summary>
/// CB790_DiscountClaim
/// Extend total claimable amount to add GST amount from all discount claim transactions
/// </summary>
/// <returns>Total claim amount = Claimable amount + admin fees + GST amount</returns>
display real displayTotalClaimAmountWithFee()
{
    return next displayTotalClaimAmountWithFee() + this.METTotalGSTAmount();
}
